{
  "application": "report-generation",
  "case_id": "case-ai-job-impact-salary-hr-en",
  "language": "en",
  "report": {
    "type": "trend-analysis",
    "audience": "executive",
    "tone": "professional, data-forward, actionable"
  },
  "brief": {
    "title": "AI Impact on the Global Job Market: Risk, Salary & Skills Trend Analysis (2015–2035)",
    "one_liner": "A comprehensive trend analysis examining how AI automation risk, salary dynamics, skill demand, and job survival prospects are evolving across roles, countries, and experience levels from 2015 to 2035.",
    "goal": "Equip executive leadership and workforce strategists with data-driven insights into which job categories face the highest automation risk, how salaries and job openings are shifting over time, and which skills and education profiles offer the strongest future-proofing — enabling informed decisions on talent investment, reskilling programs, and strategic workforce planning."
  },
  "required_sections": [
    {
      "section_id": "executive-overview",
      "title": "Executive Overview",
      "objective": "Provide a high-level summary of the dataset scope and the most critical findings regarding AI's impact on jobs, salaries, and skills across the 2015–2035 horizon."
    },
    {
      "section_id": "automation-risk-landscape",
      "title": "AI Automation Risk Landscape",
      "objective": "Analyze the distribution of AI risk scores and risk categories across job titles, countries, and experience levels. Identify the roles and regions most and least vulnerable to automation."
    },
    {
      "section_id": "salary-trends",
      "title": "Salary Trends & Segmentation",
      "objective": "Examine salary evolution over time by country, job title, experience level, and education level. Highlight salary bucket distributions and how compensation correlates with AI risk."
    },
    {
      "section_id": "skills-demand-analysis",
      "title": "Skills Demand & Future-Proofing",
      "objective": "Identify which primary skills have the highest and fastest-growing demand scores, and assess how skill demand relates to job survival classification and AI risk."
    },
    {
      "section_id": "job-survival-outlook",
      "title": "Job Survival & Market Outlook",
      "objective": "Analyze job survival class distributions and job opening trends over time. Determine which combinations of role, skill, education, and geography yield the strongest job survival prospects through 2035."
    },
    {
      "section_id": "strategic-recommendations",
      "title": "Strategic Recommendations",
      "objective": "Synthesize findings into actionable recommendations for workforce planning, reskilling investment, and talent acquisition strategy."
    }
  ],
  "kpis": [
    {
      "name": "Average AI Risk Score",
      "description": "Mean ai_risk_score across all records, segmented by job title, country, and year to track automation threat trends."
    },
    {
      "name": "Median Salary",
      "description": "Median salary value segmented by year, country, experience level, and job title to capture compensation trends."
    },
    {
      "name": "Job Survival Rate",
      "description": "Proportion of records classified as surviving (job_survival_class >= 1) versus at-risk (job_survival_class = 0), tracked over time."
    },
    {
      "name": "Average Skill Demand Score",
      "description": "Mean skill_demand_score by primary skill and year, indicating which competencies are gaining or losing market relevance."
    },
    {
      "name": "Total Job Openings Trend",
      "description": "Aggregate job_openings by year and job title to reveal expanding or contracting labor demand."
    }
  ],
  "analysis_dimensions": [
    "job_title",
    "country",
    "year",
    "experience_level",
    "primary_skill"
  ]
}

