[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>AI Impact on the Global Job Market: Risk, Salary &amp; Skills Trend Analysis (2015–2035)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --primary: #1a2e4a;
    --accent: #2563eb;
    --accent2: #0ea5e9;
    --danger: #dc2626;
    --warn: #d97706;
    --success: #16a34a;
    --neutral: #64748b;
    --bg: #f8fafc;
    --card: #ffffff;
    --border: #e2e8f0;
    --text: #0f172a;
    --text-muted: #64748b;
    --font: 'Segoe UI', system-ui, -apple-system, sans-serif;
  }
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: var(--font); background: var(--bg); color: var(--text); line-height: 1.6; }

  /* ── Layout ── */
  .page-wrap { max-width: 1200px; margin: 0 auto; padding: 0 24px 60px; }

  /* ── Header ── */
  .report-header {
    background: linear-gradient(135deg, #0f172a 0%, #1e3a5f 60%, #1d4ed8 100%);
    color: white; padding: 56px 48px 48px; margin-bottom: 40px;
    position: relative; overflow: hidden;
  }
  .report-header::after {
    content: ''; position: absolute; right: -60px; top: -60px;
    width: 320px; height: 320px; border-radius: 50%;
    background: rgba(255,255,255,0.04);
  }
  .report-header .label {
    font-size: 11px; font-weight: 700; letter-spacing: 2px; text-transform: uppercase;
    color: #93c5fd; margin-bottom: 12px;
  }
  .report-header h1 { font-size: 2.2rem; font-weight: 800; line-height: 1.25; max-width: 780px; margin-bottom: 16px; }
  .report-header .subtitle { font-size: 1rem; color: #cbd5e1; max-width: 700px; }
  .report-header .meta { margin-top: 28px; display: flex; gap: 32px; flex-wrap: wrap; }
  .report-header .meta-item { font-size: 0.8rem; color: #94a3b8; }
  .report-header .meta-item strong { display: block; font-size: 1rem; color: white; font-weight: 700; margin-top: 2px; }

  /* ── TOC ── */
  .toc-card { background: var(--card); border: 1px solid var(--border); border-radius: 12px; padding: 28px 32px; margin-bottom: 36px; }
  .toc-card h3 { font-size: 0.75rem; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: var(--text-muted); margin-bottom: 16px; }
  .toc-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: 8px; }
  .toc-item { display: flex; align-items: center; gap: 10px; padding: 8px 12px; border-radius: 8px; text-decoration: none; color: var(--text); font-size: 0.9rem; transition: background 0.15s; }
  .toc-item:hover { background: #eff6ff; color: var(--accent); }
  .toc-num { font-size: 0.75rem; font-weight: 700; color: var(--accent); width: 20px; }

  /* ── Sections ── */
  .section { margin-bottom: 52px; }
  .section-header { display: flex; align-items: baseline; gap: 14px; margin-bottom: 24px; padding-bottom: 14px; border-bottom: 2px solid var(--border); }
  .section-num { font-size: 0.7rem; font-weight: 700; letter-spacing: 1.5px; color: var(--accent); text-transform: uppercase; }
  .section-header h2 { font-size: 1.5rem; font-weight: 700; color: var(--primary); }

  /* ── KPI Cards ── */
  .kpi-row { display: grid; grid-template-columns: repeat(auto-fill, minmax(190px, 1fr)); gap: 16px; margin-bottom: 32px; }
  .kpi-card { background: var(--card); border: 1px solid var(--border); border-radius: 12px; padding: 20px 22px; position: relative; overflow: hidden; }
  .kpi-card::before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 3px; background: var(--accent); }
  .kpi-card.danger::before { background: var(--danger); }
  .kpi-card.warn::before { background: var(--warn); }
  .kpi-card.success::before { background: var(--success); }
  .kpi-card.neutral::before { background: var(--neutral); }
  .kpi-label { font-size: 0.72rem; font-weight: 700; letter-spacing: 0.8px; text-transform: uppercase; color: var(--text-muted); margin-bottom: 6px; }
  .kpi-value { font-size: 1.9rem; font-weight: 800; color: var(--primary); line-height: 1.1; }
  .kpi-sub { font-size: 0.75rem; color: var(--text-muted); margin-top: 4px; }

  /* ── Insight Callout ── */
  .insight { background: #eff6ff; border-left: 4px solid var(--accent); border-radius: 0 8px 8px 0; padding: 14px 18px; margin: 20px 0; font-size: 0.9rem; color: #1e3a5f; }
  .insight strong { display: block; margin-bottom: 4px; font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.8px; color: var(--accent); }
  .warn-insight { background: #fffbeb; border-left-color: var(--warn); color: #78350f; }
  .warn-insight strong { color: var(--warn); }
  .danger-insight { background: #fef2f2; border-left-color: var(--danger); color: #7f1d1d; }
  .danger-insight strong { color: var(--danger); }
  .success-insight { background: #f0fdf4; border-left-color: var(--success); color: #14532d; }
  .success-insight strong { color: var(--success); }

  /* ── Charts ── */
  .chart-grid { display: grid; gap: 24px; margin-bottom: 24px; }
  .chart-grid.cols-2 { grid-template-columns: 1fr 1fr; }
  .chart-grid.cols-3 { grid-template-columns: 1fr 1fr 1fr; }
  @media(max-width:800px) { .chart-grid.cols-2, .chart-grid.cols-3 { grid-template-columns: 1fr; } }
  .chart-card { background: var(--card); border: 1px solid var(--border); border-radius: 12px; padding: 22px 24px; }
  .chart-card h4 { font-size: 0.85rem; font-weight: 700; color: var(--primary); margin-bottom: 4px; }
  .chart-card .chart-sub { font-size: 0.75rem; color: var(--text-muted); margin-bottom: 16px; }
  .chart-wrap { position: relative; }

  /* ── Tables ── */
  .table-card { background: var(--card); border: 1px solid var(--border); border-radius: 12px; overflow: hidden; margin-bottom: 24px; }
  .table-card table { width: 100%; border-collapse: collapse; font-size: 0.85rem; }
  .table-card thead th { background: #f1f5f9; font-size: 0.72rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.6px; color: var(--text-muted); padding: 12px 16px; text-align: left; border-bottom: 1px solid var(--border); }
  .table-card tbody tr { border-bottom: 1px solid #f1f5f9; transition: background 0.1s; }
  .table-card tbody tr:last-child { border-bottom: none; }
  .table-card tbody tr:hover { background: #f8fafc; }
  .table-card tbody td { padding: 11px 16px; color: var(--text); }
  .badge { display: inline-block; padding: 2px 10px; border-radius: 99px; font-size: 0.72rem; font-weight: 700; }
  .badge-red { background: #fee2e2; color: #991b1b; }
  .badge-yellow { background: #fef3c7; color: #92400e; }
  .badge-green { background: #dcfce7; color: #166534; }
  .badge-blue { background: #dbeafe; color: #1e40af; }
  .badge-gray { background: #f1f5f9; color: #475569; }

  /* ── Bar fill ── */
  .bar-fill { height: 6px; border-radius: 3px; background: #e2e8f0; margin-top: 4px; }
  .bar-fill-inner { height: 100%; border-radius: 3px; background: var(--accent); }

  /* ── Recommendations ── */
  .rec-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr)); gap: 20px; }
  .rec-card { background: var(--card); border: 1px solid var(--border); border-radius: 12px; padding: 24px; position: relative; }
  .rec-card .rec-num { font-size: 0.7rem; font-weight: 700; letter-spacing: 1px; color: var(--accent); text-transform: uppercase; margin-bottom: 8px; }
  .rec-card h4 { font-size: 1rem; font-weight: 700; color: var(--primary); margin-bottom: 10px; }
  .rec-card p { font-size: 0.85rem; color: var(--text-muted); line-height: 1.65; }
  .rec-card .evidence { margin-top: 12px; padding: 10px 14px; background: #f8fafc; border-radius: 8px; font-size: 0.78rem; color: var(--text-muted); border-left: 3px solid var(--accent); }
  .rec-card .evidence strong { color: var(--accent); }

  /* ── Footer ── */
  .report-footer { text-align: center; padding: 32px; border-top: 1px solid var(--border); margin-top: 48px; font-size: 0.8rem; color: var(--text-muted); }

  /* ── Executive highlight ── */
  .exec-findings { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 16px; margin-bottom: 28px; }
  .exec-finding { background: var(--card); border: 1px solid var(--border); border-radius: 12px; padding: 20px; display: flex; gap: 14px; align-items: flex-start; }
  .exec-finding .icon { font-size: 1.4rem; flex-shrink: 0; margin-top: 2px; }
  .exec-finding h4 { font-size: 0.85rem; font-weight: 700; color: var(--primary); margin-bottom: 4px; }
  .exec-finding p { font-size: 0.8rem; color: var(--text-muted); line-height: 1.55; }

  /* ── Risk meter ── */
  .risk-meter { display: flex; align-items: center; gap: 8px; }
  .risk-dot { width: 10px; height: 10px; border-radius: 50%; flex-shrink: 0; }
</style>
</head>
<body>

<!-- ══════════════════════════════════════════════════════════ HEADER -->
<div class="report-header">
  <div class="page-wrap" style="padding-top:0;padding-bottom:0;">
    <div class="label">Workforce Intelligence Report</div>
    <h1>AI Impact on the Global Job Market:<br>Risk, Salary &amp; Skills Trend Analysis</h1>
    <p class="subtitle">A comprehensive examination of how AI automation risk, salary dynamics, skill demand, and job survival prospects are evolving across roles, countries, and experience levels from 2015 to 2035.</p>
    <div class="meta">
      <div class="meta-item"><strong>2015 – 2035</strong>Analysis Horizon</div>
      <div class="meta-item"><strong>12,343</strong>Records Analyzed</div>
      <div class="meta-item"><strong>10 Job Roles</strong>Across 6 Countries</div>
      <div class="meta-item"><strong>April 2026</strong>Report Date</div>
    </div>
  </div>
</div>

<div class="page-wrap">

<!-- ══════════════════════════════════════════════════════════ TOC -->
<div class="toc-card">
  <h3>Contents</h3>
  <div class="toc-grid">
    <a href="#s1" class="toc-item"><span class="toc-num">01</span> Executive Overview</a>
    <a href="#s2" class="toc-item"><span class="toc-num">02</span> AI Automation Risk Landscape</a>
    <a href="#s3" class="toc-item"><span class="toc-num">03</span> Salary Trends &amp; Segmentation</a>
    <a href="#s4" class="toc-item"><span class="toc-num">04</span> Skills Demand &amp; Future-Proofing</a>
    <a href="#s5" class="toc-item"><span class="toc-num">05</span> Job Survival &amp; Market Outlook</a>
    <a href="#s6" class="toc-item"><span class="toc-num">06</span> Strategic Recommendations</a>
  </div>
</div>


<!-- ══════════════════════════════════════════════════════════ S1: EXECUTIVE OVERVIEW -->
<section class="section" id="s1">
  <div class="section-header">
    <span class="section-num">01</span>
    <h2>Executive Overview</h2>
  </div>

  <div class="kpi-row">
    <div class="kpi-card">
      <div class="kpi-label">Avg AI Risk Score (2035)</div>
      <div class="kpi-value">0.51</div>
      <div class="kpi-sub">Up from 0.30 in 2015 (+72%)</div>
    </div>
    <div class="kpi-card danger">
      <div class="kpi-label">Highest-Risk Role</div>
      <div class="kpi-value">0.85</div>
      <div class="kpi-sub">Business Analyst by 2035</div>
    </div>
    <div class="kpi-card success">
      <div class="kpi-label">Job Survival Rate</div>
      <div class="kpi-value">89%</div>
      <div class="kpi-sub">Class ≥1 across all records</div>
    </div>
    <div class="kpi-card warn">
      <div class="kpi-label">Median Global Salary</div>
      <div class="kpi-value">$31.6K</div>
      <div class="kpi-sub">Dataset-wide median (USD)</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-label">Salary Premium (Low vs. High Risk)</div>
      <div class="kpi-value">+60%</div>
      <div class="kpi-sub">Low-risk jobs vs. high-risk jobs</div>
    </div>
  </div>

  <div class="exec-findings">
    <div class="exec-finding">
      <div class="icon">📈</div>
      <div>
        <h4>Automation Threat Is Accelerating</h4>
        <p>The average AI risk score across all roles grew from 0.30 in 2015 to a projected 0.51 by 2035 — a 72% increase. Business Analyst and Data Analyst roles are on a near-certain automation trajectory, reaching risk scores of 0.85 and 0.75 respectively by 2035.</p>
      </div>
    </div>
    <div class="exec-finding">
      <div class="icon">💵</div>
      <div>
        <h4>Lower Risk Commands a 60% Salary Premium</h4>
        <p>Jobs in the Low Risk category command a median salary ~60% higher than High Risk jobs ($34.1K vs. $21.7K). This gap widens significantly through the projection period, with Low Risk roles reaching $49K median by 2035 vs. $24K for High Risk.</p>
      </div>
    </div>
    <div class="exec-finding">
      <div class="icon">🧠</div>
      <div>
        <h4>Deep Learning &amp; Python Are the Strongest Shields</h4>
        <p>Deep Learning skill holders achieve Class-2 (strong survival) outcomes 88.9% of the time. Python follows at 57.9%. In contrast, Excel and SQL workers show 0% Class-2 survival rates, placing them firmly in the at-risk tier.</p>
      </div>
    </div>
    <div class="exec-finding">
      <div class="icon">🌍</div>
      <div>
        <h4>USA Leads in Both Salaries and Survival Rates</h4>
        <p>US-based workers earn a median $43.4K (vs. $12.4K in India) and 58% achieve Class-2 survival — the highest of any country. India trails at only 8.8% Class-2 survival, signaling acute vulnerability to automation displacement.</p>
      </div>
    </div>
    <div class="exec-finding">
      <div class="icon">🔍</div>
      <div>
        <h4>AI Researcher &amp; ML Engineer Roles Are Future-Proof</h4>
        <p>AI Researchers have a mere 0.15 average risk score (0.25 by 2035) and 88.9% Class-2 survival. ML Engineers mirror this pattern at 71.2% Class-2. These are the highest-value talent categories for the next decade.</p>
      </div>
    </div>
    <div class="exec-finding">
      <div class="icon">⚠️</div>
      <div>
        <h4>At-Risk Job Share Rising Through 2035</h4>
        <p>Class-0 (at-risk) jobs represented 8.9% of records in 2015–2016 but climbed to 16.3% by 2035, signaling an expanding population of workers needing proactive reskilling intervention within the next decade.</p>
      </div>
    </div>
  </div>

  <div class="insight">
    <strong>Data Scope Note</strong>
    This analysis covers 12,343 synthetic records spanning 2015–2035 across 10 job titles, 6 countries, and 9 primary skills. Years 2025–2035 represent trend-based projections, not observed data. All salary figures are in USD nominal terms.
  </div>
</section>


<!-- ══════════════════════════════════════════════════════════ S2: AUTOMATION RISK -->
<section class="section" id="s2">
  <div class="section-header">
    <span class="section-num">02</span>
    <h2>AI Automation Risk Landscape</h2>
  </div>

  <p style="color:var(--text-muted);font-size:0.9rem;margin-bottom:24px;">The <em>ai_risk_score</em> (0–1) measures the probability that a job will be significantly impacted or automated by AI. Scores above 0.6 represent acute, near-term displacement risk.</p>

  <div class="chart-grid cols-2">
    <div class="chart-card">
      <h4>AI Risk Score Trend by Year</h4>
      <div class="chart-sub">Average ai_risk_score across all roles, 2015–2035</div>
      <div class="chart-wrap"><canvas id="riskTrendChart" height="220"></canvas></div>
    </div>
    <div class="chart-card">
      <h4>Risk Category Distribution</h4>
      <div class="chart-sub">Proportion of records in each risk tier (dataset-wide)</div>
      <div class="chart-wrap"><canvas id="riskCatChart" height="220"></canvas></div>
    </div>
  </div>

  <div class="chart-grid cols-2">
    <div class="chart-card">
      <h4>Average AI Risk Score by Job Title</h4>
      <div class="chart-sub">Dataset-average — sorted high to low risk</div>
      <div class="chart-wrap"><canvas id="riskJobChart" height="300"></canvas></div>
    </div>
    <div class="chart-card">
      <h4>AI Risk Trajectories: Selected Roles (2015–2035)</h4>
      <div class="chart-sub">Annual avg risk score for highest &amp; lowest risk roles</div>
      <div class="chart-wrap"><canvas id="riskTrajectoryChart" height="300"></canvas></div>
